DROP TABLE IF EXISTS necro_thread;CREATE TABLE necro_thread (	id INT NOT NULL AUTO_INCREMENT,	title VARCHAR(255),	created DATETIME NOT NULL,	last_mod DATETIME NOT NULL,	PRIMARY KEY(thread_id));DROP TABLE IF EXISTS necro_thread_recipients;CREATE TABLE necro_thread_recipients (	thread_id INT NOT NULL,	user_id INT NOT NULL,	is_admin TINYINT NOT NULL DEFAULT `0`,	INDEX idx_thread_recipient_map (thread_id, user_id));DROP TABLE IF EXISTS necro_thread_message;CREATE TABLE necro_thread_message (		id INT NOT NULL AUTO_INCREMENT,	thread_id INT NOT NULL,	sending_user_id INT NOT NULL,	message TEXT,	created DATETIME NOT NULL,	last_mod DATETIME NOT NULL,	PRIMARY KEY(message_id),	INDEX idx_thread_messages(thread_id),	INDEX idx_thread_user_messages(thread_id, sending_user_id));